<script lang="ts">
 import {onMount,onDestroy} from 'svelte';import CompanySocialOAuthCallback from '$lib/components/enterprise/social/CompanySocialOAuthCallback.svelte';import AutomationOAuthCallback from '$lib/components/enterprise/automations/AutomationOAuthCallback.svelte';
 const access=new AbortController();let provider='',mounted=false;const supported=new Set(['slack','shopify','social']);onMount(()=>{provider=/^\/app\/integrations\/([^/]+)\/callback\/?$/.exec(location.pathname)?.[1]||'';mounted=true;if(!supported.has(provider))history.replaceState(history.state,'',location.pathname);});
 function resume(value:{companyId:string;conversationId:string;draftId:string|null}){const query=new URLSearchParams({automationCompany:value.companyId,automationRoom:value.conversationId});if(value.draftId)query.set('automationDraft',value.draftId);location.replace('/app?'+query.toString());}
 onDestroy(()=>access.abort());
</script>
<svelte:head><title>Secure sign-in · Starli Integrations</title><meta name="referrer" content="no-referrer"/></svelte:head>
<main>{#if !mounted}<p>Opening secure sign-in…</p>{:else if supported.has(provider)}{#key provider}{#if provider==='social'}<CompanySocialOAuthCallback accessSignal={access.signal} on:resumed={event=>resume(event.detail)}/>{:else}<AutomationOAuthCallback providerId={provider} accessSignal={access.signal} on:resumed={event=>resume(event.detail)}/>{/if}{/key}{:else}<section><h1>Integration not supported</h1><p>Return to the original conversation to connect an available business app.</p><a href="/app">Return to Starli</a></section>{/if}</main>
<style>main{min-height:100vh;padding:20px;background:#f6f8fc;color:#17243f;font-family:'Mona Sans',sans-serif}section{max-width:560px;margin:50px auto;padding:28px;background:white;border:1px solid #e6ebf4;border-radius:12px}h1{font-size:20px;font-weight:500}p,a{font-size:13px;line-height:1.8}p{color:#71809a}a{color:#3466f6}@media(max-width:500px){main{padding:15px}}</style>
